/**
 * TODO: if you have formal awards or certifications, replace these career
 * milestones with the real thing — the layout is identical.
 */
export const milestones = {
	title: "Milestones & Highlights",
	items: [
		{
			title: "Front-end architecture & design system for StrategyR",
			year: "2020 – Present",
			award: "Resx Analytics LLP",
			link: "/portfolio/strategyr",
		},
		{
			title: "UX design for the MarketGlass intelligence platform",
			year: "2020 – Present",
			award: "Resx Analytics LLP",
			link: "/portfolio/marketglass",
		},
		{
			title: "eSmart Permit — workflow automation interface",
			year: "2019 – 2020",
			award: "iSpatial Techno Solutions",
			link: "/portfolio/esmart-permit",
		},
		{
			title: "Enterprise research portals & marketing sites",
			year: "2013 – 2019",
			award: "BizAcumen Research",
			link: "/portfolio/ispatialtech",
		},
	],
};

export const strengths = {
	title: "Strengths",
	items: [
		{
			description:
				"Dedicated to the work and an effective team lead — I keep design and development moving in the same direction with clear handoff and documentation.",
		},
		{
			description:
				"A problem-solver by instinct. I enjoy untangling other people's blockers as much as my own, and I keep the tone light while doing it.",
		},
		{
			description:
				"Continuously self-taught. Every year of the last fourteen has added a tool, a framework or a method — most recently an AI-assisted workflow end to end.",
		},
		{
			description:
				"Strong at translating requirements into scope, and then into an interface that delivers exactly what the team asked for.",
		},
	],
};
